entries[108421] = { ["name"] = "Plans: Blackrock Crucibles and Their Uses", ["text"] = "Binds when picked up\nUnique\nRequires Blacksmithing (600)\n\"Teaches you how to create Blackrock Crucibles that produce Draenic Steel Ingots and Blackrock ingots. Also teaches you a recipe that uses the ingots.\"" }
