entries[108423] = { ["name"] = "Thaelin's Call", ["text"] = "Quest Item\nUnique\nUse: Calls Thaelin Darkanvil in for a bombing run against the Arkonite Protector, that deals 19 Physical damage and stuns the target for 10 sec." }
