entries[109161] = { ["name"] = "Thaelin's Quick Fix", ["text"] = "Quest Item\nUnique\nUse: Deploys a device to 'fix' Iron Horde targets. (15 Sec Cooldown)" }
entries[109162] = { ["name"] = "Grimoire of Binding", ["text"] = "Quest Item\n\"Contains spells and incantations used to bind magical power to living beings.\"" }
entries[109163] = { ["name"] = "Ango'rosh Spellbook", ["text"] = "Quest Item\n\"Advisory: Spells of raw power. Do not attempt to wield, control, or bind.\"" }
entries[109164] = { ["name"] = "Sticky Tarbomb", ["text"] = "Quest Item\nUse: Throw a Sticky Tarbomb to destroy Incubator Cages within Agurak's Fall.\n\"Do not expose to open flame until ready for use.\"" }
