entries[109167] = { ["name"] = "Findle's Loot-A-Rang", ["text"] = "Binds when used\nToy\nUse: Retrieves the loot from a nearby corpse. Can only be used in Draenor. (3 Sec Cooldown)\nSell Price:" }
