entries[109183] = { ["name"] = "World Shrinker", ["text"] = "Toy\nUse: Shrinks the entire world for 5 min or until you attack. (15 Min Cooldown)\nRequires Draenor Engineering (1)\n\"Overuse may result in permanent shrinkage.\"\nSell Price:" }
entries[109184] = { ["name"] = "Stealthman 54", ["text"] = "Use: Cloaks the user in a stealth field for as long as they stand still. Cannot be used in combat. The field lasts for up to 6 sec. after moving.\n\nThe Stealthman shares a cooldown with non-healing potions. Ineffective above level 49. (5 Min Cooldown)\n\"Invisibility is for suckers!\"\nSell Price:" }
entries[109186] = { ["name"] = "Hagra's Shard", ["text"] = "Quest Item\n\"Touching the shard gives you the feeling that your soul is being covered by something oily and foul.\"" }
entries[109187] = { ["name"] = "Grogal's Shard", ["text"] = "Quest Item\n\"The fel taint within resonates as if something is trying to escape.\"" }
entries[109192] = { ["name"] = "Lightbearer", ["text"] = "\"This worn mace once belonged to a guardian of Shattrath. Light still emanates from within, though it has begun to fade.\"\nSell Price:" }
entries[109196] = { ["name"] = "Battle-Worn Frostwolf Banner", ["text"] = "Quest Item\nUnique\nUse: Place a Battle-Worn Frostwolf Banner upon the corpses of slain thunderlords within the Ribbreaker Warcamp. (2 Sec Cooldown)" }
entries[109197] = { ["name"] = "Auch'naaru", ["text"] = "Quest Item\n\"One of the three fragments of the Heart of Auchindoun.\"" }
entries[109205] = { ["name"] = "Fiery Heart", ["text"] = "Quest Item\n\"Still burning with demonic heat.\"" }
entries[109206] = { ["name"] = "Burning Torch", ["text"] = "Quest Item\n\"The first rule of fire safety is to keep burning torches away from flammable objects.\"" }
entries[109217] = { ["name"] = "Draenic Agility Potion", ["text"] = "Use: Increases your Agility by 116 for 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[109218] = { ["name"] = "Draenic Intellect Potion", ["text"] = "Use: Increases your Intellect by 116 for 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[109219] = { ["name"] = "Draenic Strength Potion", ["text"] = "Use: Increases your Strength by 116 for 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[109220] = { ["name"] = "Draenic Versatility Potion", ["text"] = "Use: Increases your Versatility by 31 for 25 sec. (5 Min Cooldown)\nSell Price:" }
entries[109221] = { ["name"] = "Draenic Channeled Mana Potion", ["text"] = "Use: Puts the imbiber in an elevated state of focus where they can restore up to ( 255 * 10) mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)\nSell Price:" }
entries[109222] = { ["name"] = "Draenic Mana Potion", ["text"] = "Use: Restores 1700 mana. (5 Min Cooldown)\nSell Price:" }
entries[109223] = { ["name"] = "Healing Tonic", ["text"] = "Use: Restores 3400 health. (5 Min Cooldown)\n\"Prepared properly, the venom of the Sea Scorpion can restore health.\"\nSell Price:" }
entries[109224] = { ["name"] = "Gul'var Soul Shards", ["text"] = "Quest Item\nUse: Combine the soul shards at the forge in Gul'var to create Gul'dan's Soul Trap." }
entries[109225] = { ["name"] = "Gul'dan's Soul Trap", ["text"] = "Quest Item\nUnique\n\"The sum feels far greater than the parts.\"" }
entries[109226] = { ["name"] = "Draenic Rejuvenation Potion", ["text"] = "Use: Restores 3400 health and 850 mana. (5 Min Cooldown)\nSell Price:" }
entries[109246] = { ["name"] = "Gul'dan's Soul Trap", ["text"] = "Quest Item\nUse: Ensnare Gul'dan's soul, imprisoning him for return to Archmage Khadgar at Starfall Outpost. (20 Sec Cooldown)" }
entries[109248] = { ["name"] = "Siege Weapon Schematics", ["text"] = "Quest Item\nUnique\n\"The weapon detailed in these blueprints is both savage and brutal.\"" }
entries[109250] = { ["name"] = "Quickcharge Jumper Cables", ["text"] = "Sell Price:" }
entries[109252] = { ["name"] = "Engineer's Gnomish Army Knife", ["text"] = "Socket Bonus: Block Level 27\nRequires Engineering (600)\n\"Includes Gyromatic Micro-Adjustor, Arclight Spanner, Jeweler's Kit, Blacksmithing Hammer, Nail File, and Virtuoso Inking Set.\"\nSell Price:" }
entries[109253] = { ["name"] = "Ultimate Gnomish Army Knife", ["text"] = "+10 Draenor Mining Skill.\n+10 Draenor Herbalism Skill.\n+10 Draenor Skinning Skill.\n\"Includes every profession tool.\"\nSell Price:" }
entries[109254] = { ["name"] = "Lumber Mill, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Garrison Lumber Mill building to level 2.\n\nLevel 1\nAllows you to mark small trees in Draenor for harvest. Harvested Timber can be converted to work orders for garrison supplies.\n\nLevel 2\nAllows you to mark medium trees for additional Timber.\n\nLevel 3\nAllows you to mark large trees for even more Timber.\nRequires Spires of Arak Outpost questline or level 35.\nSell Price:" }
entries[109255] = { ["name"] = "Lumber Mill, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Garrison Lumber Mill building to level 3.\n\nLevel 1\nAllows you to mark small trees in Draenor for harvest. Harvested Timber can be converted to work orders for garrison supplies.\n\nLevel 2\nAllows you to mark medium trees for additional Timber.\n\nLevel 3\nAllows you to mark large trees for even more Timber.\nRequires Achievement: Upgrading The Mill\nSell Price:" }
entries[109256] = { ["name"] = "Engineering Works, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Engineering Works building to level 2.\n\nLevel 1\nAllows the production of Engineering items and work orders.\n\nLevel 2\nAllows followers with the Engineering trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Engineering missions, and allows up to 21 work orders at one time.\nRequires Talador Outpost questline or level 30.\nSell Price:" }
entries[109257] = { ["name"] = "Engineering Works, Level 3", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Engineering Works building to level 3.\n\nLevel 1\nAllows the production of Engineering items and work orders.\n\nLevel 2\nAllows followers with the Engineering trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Engineering missions, and allows up to 21 work orders at one time.\nRequires Achievement: Working More Orders\nSell Price:" }
entries[109258] = { ["name"] = "Engineering Works, Level 1", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build an Engineering Works building in your Garrison.\n\nLevel 1\nAllows the production of Engineering items and work orders.\n\nLevel 2\nAllows followers with the Engineering trait to work here, granting a unique bonus. Also allows up to 14 work orders at one time.\n\nLevel 3\nUnlocks Engineering missions, and allows up to 21 work orders at one time.\nSell Price:" }
entries[109259] = { ["name"] = "Shadow Council Spellbook", ["text"] = "Quest Item\n\"If found, cast the spell on page 42.\"" }
entries[109261] = { ["name"] = "Alchemist's Cauldron", ["text"] = "Binds when picked up\n\"Yields Metamorphic Crystals and Alchemical Catalysts.\"\n<Right Click to Open>" }
entries[109262] = { ["name"] = "Draenic Philosopher's Stone", ["text"] = "Binds when picked up\nUnique-Equipped: Alchemist Stone (1)\nTrinket\n+ 4 Mastery\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 55s cooldown)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Draenor Alchemy (1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"\nSell Price:" }
entries[109557] = { ["name"] = "Mutation Serum", ["text"] = "Quest Item\nUnique\n\"Use on Grulk to restore his mutant strength.\"" }
entries[109558] = { ["name"] = "A Treatise on the Alchemy of Draenor", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you Draenor Alchemy and a number of recipes.\nRequires Alchemy (1)\n\"An introduction to the secrets of the alchemy of Draenor.\"" }
entries[109566] = { ["name"] = "Baby Rylak", ["text"] = "Quest Item\nUnique\n\"This baby rylak will make a perfect gift.\"" }
entries[109574] = { ["name"] = "GUMM-E", ["text"] = "Binds when used\nUnique: Engineering Workshop Item (1)\nUse: Creates a portable mailbox for 5 min. (3 Hrs Cooldown)\n3 Charges\n\"Normally too complicated for the common person, this particular mailbox has extra-large buttons and instructions on it.\"\nSell Price:" }
entries[109575] = { ["name"] = "Auch'naaru", ["text"] = "Quest Item\n\"One of the three fragments of the Heart of Auchindoun.\"" }
entries[109576] = { ["name"] = "Lunarfall Excavation, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nRequires any Alliance race\nUse: Provides the plans needed to upgrade your Lunarfall Excavation to level 2.\n\nLevel 1\nAllows players to mine Draenic Stone from mineral nodes in Draenor. Draenic Stone can be converted to work orders for Draenor minerals.\n\nLevel 2\nAllows followers with the Mining trait to work here, granting a unique bonus. Also opens a new mineshaft, granting access to additional mining nodes and allows up to 14 work orders at one time.\n\nLevel 3\nA final mineshaft allows access to rich mining nodes. In addition, garrison guards will patrol your mine, keeping it clear of hostile goren. Also allows up to 21 work orders at one time.\nRequires Mine\nSell Price:" }
entries[109577] = { ["name"] = "Herb Garden, Level 2", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to upgrade your Herb Garden to level 2.\n\nLevel 1\nGrows Draenic Seeds into herbs each day and herbalism nodes are available in the garden.\n\nLevel 2\nAllows followers with the Herbalism trait to work here, granting a unique bonus. Also increases the amount of herbs that can be harvested at the garden and allows up to 14 work orders at one time.\n\nLevel 3\nGrow a unique Draenor fruit tree in your garden that grants food buffs. Also allows up to 21 work orders at one time.\nRequires Herb Garden\nSell Price:" }
entries[109578] = { ["name"] = "Fishing Shack", ["text"] = "Garrison Blueprint\nBinds when picked up\nUnique\nUse: Provides the plans needed to build the Garrison Fishing Shack.\n\nLevel 1\nAllows small Draenor fish to be caught in garrison waters and provides access to daily Fishing quests.\n\nLevel 2\nAllows medium Draenor fish to be caught in garrison waters.\n\nLevel 3\nAllows enormous Draenor fish to be caught in garrison waters. Also grants you a chance to catch a unique fish that can be used to lure mysterious creatures onto the shore.\nSell Price:" }
entries[109580] = { ["name"] = "Warlords Intro Zone - Str Shield", ["text"] = "Binds when picked up\nThis Item Begins a Quest\nOff Hand Shield\n9384 Armor\n+520 Strength\n+2,378 Stamina\n+ 231 Critical Strike\n+ 307 Mastery\nDurability 85 / 85\n<Right Click to Read>\nSell Price:" }
entries[109581] = { ["name"] = "Weapon - Axe_1h_DraenorQuest_B_01 - Orange (Thrown)", ["text"] = "Unknown Thrown\nSocket Bonus: Block Level 27" }
entries[109584] = { ["name"] = "Ogre Missive", ["text"] = "\"Keystone that can complete Ogre archaeology artifacts with missing fragments.\"\nSell Price:" }
entries[109585] = { ["name"] = "Arakkoa Cipher", ["text"] = "\"Keystone that can complete Arakkoa archaeology artifacts with missing fragments.\"\nSell Price:" }
entries[109586] = { ["name"] = "Brittle Cartography Journal", ["text"] = "Binds when picked up\nUnique\nRequires Archaeology (1)\n\"Teaches you Draenor Archaeology.\"" }
entries[109591] = { ["name"] = "Dungeon Key", ["text"] = "Quest Item\nUnique\n\"If there is a skull on the handle it must be a dungeon key.\"" }
entries[109592] = { ["name"] = "Key to Corki's Cage", ["text"] = "Quest Item\nUse: Unlocks Corki's Prison.\n\"This rod iron key has seen a lot of re-use.\"" }
entries[109599] = { ["name"] = "Neural Silencer", ["text"] = "Use: Makes you immune to some annoyances. Persists through death. Lasts 12 hrs.\n\"Annoyances include Leap of Faith, threat redirecting abilities, and some gadgets like the Swapblaster.\"\nSell Price:" }
entries[109601] = { ["name"] = "Indalamar's Newer Holy Hand Grenade", ["text"] = "Binds when picked up\nUnique\nUse: Blesses all targets with a holy infusion of power or curse them with the bane of all raiders.\nSell Price:" }
entries[109602] = { ["name"] = "Echo of Murmur [TEMP ITEM & SPELL]", ["text"] = "Use: Teaches you how to summon this companion.\nRight Click to summon and dismiss your terrible turnip.\nRequires level 1 to 80 ( 80)" }
