entries[109644] = { ["name"] = "Walter", ["text"] = "Binds when picked up\nUnique: Engineering Workshop Item (1)\nUse: Attempts to assemble Walter, the world's laziest waiter and butler, who might help out for up to 6 min.\n\nWalter can begrudgingly grant bank access to his creator. For everyone else, he sells some fairly terrible food. (2 Hrs Cooldown)\n3 Charges\nSell Price:" }
entries[109645] = { ["name"] = "Blackrock Seaforium", ["text"] = "Use: Blasts open locked doors and chests that require lockpicking skill of 475 and below.\nRequires Draenor Engineering (1)\nSell Price:" }
entries[109649] = { ["name"] = "Small Crescent Saberfish", ["text"] = "\"Found everywhere in Draenor. Silvery eel with many, many sharp little teeth. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109650] = { ["name"] = "Small Jawless Skulker", ["text"] = "\"A strange fish with no mouth and an unforked tail. Subsists on the life energy of plants. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109651] = { ["name"] = "Small Fat Sleeper", ["text"] = "\"Ugly and slimy. Surprisingly delicious when cooked. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109652] = { ["name"] = "Small Blind Lake Sturgeon", ["text"] = "\"Lacking eyes, it \"sees\" with its long whiskers. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109653] = { ["name"] = "Small Fire Ammonite", ["text"] = "\"A magical \"fish\" that lives in lava and looks like a squid in a cone shaped shell. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109654] = { ["name"] = "Small Sea Scorpion", ["text"] = "\"Careful. It could take off one of your fingers with its pincers. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109655] = { ["name"] = "Small Abyssal Gulper Eel", ["text"] = "\"With a ridiculously oversized head and mouth, it can swallow prey bigger than itself. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109656] = { ["name"] = "Small Blackwater Whiptail", ["text"] = "Crafting Reagent\n\"Has a powerful tail, which it uses to stun its prey. Requires little skill to catch.\"\n<Right Click to Open>" }
entries[109693] = { ["name"] = "Draenic Dust", ["text"] = "Crafting Reagent" }
